def iou(a, b):
    ax1, ay1, ax2, ay2 = a; bx1, by1, bx2, by2 = b
    ix1, iy1 = max(ax1, bx1), max(ay1, by1)
    ix2, iy2 = min(ax2, bx2), min(ay2, by2)
    inter = max(0, ix2-ix1) * max(0, iy2-iy1)
    area_a = max(0, ax2-ax1) * max(0, ay2-ay1)
    area_b = max(0, bx2-bx1) * max(0, by2-by1)
    union = area_a + area_b - inter
    return inter / union if union > 0 else 0.0
# Persistent per-input state: tracks = []; next_id = 1.
def new_track(det, track_id):
    box = det['box']
    center = (int((box[0]+box[2])/2), int((box[1]+box[3])/2))
    return {'id': track_id, 'box': box, 'score': det['score'], 'misses': 0, 'hits': 1, 'trail': [center]}
if not tracks:
    for det in people:
        tracks.append(new_track(det, next_id)); next_id += 1
else:
    if people:
        cost = np.zeros((len(tracks), len(people)))
        for i, trk in enumerate(tracks):
            for j, det in enumerate(people): cost[i, j] = 1 - iou(trk['box'], det['box'])
        row_idx, col_idx = scipy.optimize.linear_sum_assignment(cost)
    else:
        row_idx, col_idx = np.array([], dtype=int), np.array([], dtype=int)
    matched_tracks, matched_dets = set(), set()
    for r, c in zip(row_idx, col_idx):
        if 1 - cost[r, c] >= 0.3:
            trk, det = tracks[r], people[c]
            trk['box'], trk['score'] = det['box'], det['score']
            trk['hits'] += 1; trk['misses'] = 0
            box = trk['box']
            trk['trail'].append((int((box[0]+box[2])/2), int((box[1]+box[3])/2)))
            trk['trail'] = trk['trail'][-30:]
            matched_tracks.add(r); matched_dets.add(c)
    for i, trk in enumerate(tracks):
        if i not in matched_tracks: trk['misses'] += 1
    for j, det in enumerate(people):
        if j not in matched_dets:
            tracks.append(new_track(det, next_id)); next_id += 1
    tracks = [trk for trk in tracks if trk['misses'] <= 15]
# Retain missed tracks for association, but emit only current observations.
return [dict(trk) for trk in tracks if trk['misses'] == 0]

